:root {
  --bg: #fff; --fg: #1f2933; --muted: #6b7280; --line: #e4e7eb;
  --accent: #1f2933; --bad: #c0392b; --good: #0a7b3e; --soft: #f5f7fa;
}
/* Mine's theme setting is "system" by default, so the device decides; light and dark are the
   two overrides, and the attribute is what carries them. */
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) { --bg: #15191e; --fg: #e8eaed; --muted: #9aa5b1; --line: #2b3138;
    --accent: #e8eaed; --bad: #ff8a7a; --good: #5bd48b; --soft: #1d2229; }
}
:root[data-theme="dark"] { --bg: #15191e; --fg: #e8eaed; --muted: #9aa5b1; --line: #2b3138;
    --accent: #e8eaed; --bad: #ff8a7a; --good: #5bd48b; --soft: #1d2229; }
* { box-sizing: border-box; }
body {
  margin: 0; padding: 16px max(16px, env(safe-area-inset-left)) 24px;
  max-width: 44rem; margin-inline: auto;
  font: 16px/1.5 system-ui, -apple-system, sans-serif;
  color: var(--fg); background: var(--bg);
}
header { display: flex; align-items: center; justify-content: space-between; gap: 1rem; }
h1 { font-size: 1.4rem; margin: .2rem 0 .6rem; }
.lede { color: var(--muted); margin-top: 0; }

label { display: block; margin: .9rem 0; font-size: .85rem; color: var(--muted); }
input {
  display: block; width: 100%; margin-top: .3rem; padding: .75rem;
  font: inherit; color: var(--fg); background: var(--bg);
  border: 1px solid var(--line); border-radius: .5rem;
}
button {
  width: 100%; padding: .9rem; margin: .4rem 0; font: inherit; font-weight: 600;
  color: var(--bg); background: var(--accent);
  border: 0; border-radius: .6rem; cursor: pointer;
}
button[disabled] { opacity: .5; }
button.danger { color: var(--bad); background: none; border: 1px solid var(--line); }
.icon-btn {
  width: auto; padding: .4rem .7rem; font-size: 1.1rem; line-height: 1;
  color: var(--fg); background: none; border: 1px solid var(--line);
  border-radius: .5rem; text-decoration: none;
}

.tiles { display: grid; grid-template-columns: repeat(auto-fill, minmax(7rem, 1fr)); gap: .8rem; margin: 1rem 0; }
.tile {
  display: flex; flex-direction: column; align-items: center; gap: .5rem;
  padding: 1.2rem .5rem; text-decoration: none; color: var(--fg);
  background: var(--soft); border-radius: .8rem;
}
.tile img { width: 2.2rem; height: 2.2rem; }
.tile span { font-size: .85rem; }

dl { display: grid; grid-template-columns: auto 1fr; gap: .4rem 1rem; margin: 1rem 0; font-size: .9rem; }
dt { color: var(--muted); }
dd { margin: 0; word-break: break-word; }

.status, .msg { font-size: .85rem; color: var(--muted); }
.bad { color: var(--bad); }
.banner {
  padding: .7rem .9rem; margin: .6rem 0; font-size: .85rem;
  background: var(--soft); border-left: 3px solid var(--bad); border-radius: .3rem;
}
.banner.update {
  position: fixed; inset: auto 1rem 1rem; display: flex; align-items: center;
  justify-content: space-between; gap: 1rem; border-left-color: var(--good);
  box-shadow: 0 2px 12px rgb(0 0 0 / .18);
}
.banner.update button { width: auto; padding: .45rem .9rem; }

.steps { padding-left: 1.2rem; font-size: .85rem; color: var(--muted); }
.steps li { margin: .35rem 0; }
.steps li.done { color: var(--good); }
.steps li.bad { color: var(--bad); }

/* The two settings that belong to Mine rather than to one app. */
.prefs { margin: 1rem 0; }
.prefrow { display: flex; align-items: center; gap: .6rem; padding: .55rem 0; border-top: 1px solid var(--line); }
.prefrow span { flex: 1; font-size: .85rem; }
.prefrow select { width: auto; min-width: 8rem; margin: 0; padding: .5rem; font: inherit;
  color: var(--fg); background: var(--bg); border: 1px solid var(--line); border-radius: .5rem; }
.prefs .note { margin: .5rem 0 0; font-size: .75rem; color: var(--muted); }
