#!/bin/bash
# Runs the model checks in node, then starts the fixture server and a headless Chromium for the
# browser checks and tears both down.
#
#   test/run.sh              the checks
#   test/run.sh --shot DIR   the checks, and a screenshot of each view into DIR
#
# Needs chromium and node 20+ on PATH. Nothing is installed and nothing is written to the repo.
set -u
HERE=$(cd "$(dirname "$0")" && pwd)
PORT=8787
PROFILE=$(mktemp -d)

cleanup() {
  [ -n "${CHROME:-}" ] && kill "$CHROME" 2>/dev/null
  [ -n "${SERVER:-}" ] && kill "$SERVER" 2>/dev/null
  rm -rf "$PROFILE"
}
trap cleanup EXIT

command -v chromium >/dev/null || { echo "chromium not on PATH"; exit 2; }

node "$HERE/unit.mjs" || exit 1

python3 "$HERE/serve.py" $PORT >/dev/null 2>&1 &
SERVER=$!
chromium --headless --no-sandbox --disable-gpu --hide-scrollbars --no-first-run \
  --disable-extensions --remote-debugging-port=9222 --user-data-dir="$PROFILE" \
  about:blank >/dev/null 2>&1 &
CHROME=$!

for i in $(seq 30); do
  curl -sf -o /dev/null "http://127.0.0.1:$PORT/calendar/" && break
  sleep 0.2
done

# Node 20 keeps WebSocket behind a flag; 21+ ignores the flag harmlessly.
node --experimental-websocket "$HERE/check.mjs" "$@" 2>&1 | grep -v 'ExperimentalWarning\|Use `node'
exit "${PIPESTATUS[0]}"
=== check.mjs head ===
// The browser checks. Run through test/run.sh, which starts the server and Chromium for it.
//
// Chromium is driven over CDP rather than with --window-size and --screenshot, because that
// flag pair lays the page out at a fixed 500px and only scales the capture: a 320px screenshot
// of a 500px layout passes a fit check that a real phone fails. Emulation.setDeviceMetricsOverride
// is the width the page actually sees.
//
// Node 20 has no WebSocket global, hence --experimental-websocket in run.sh.
const PORT = 8787, CDP = 9222, ORIGIN = `http://127.0.0.1:${PORT}`;
const SHOT = process.argv.includes('--shot') ? process.argv[process.argv.indexOf('--shot') + 1] : null;

const sleep = ms => new Promise(r => setTimeout(r, ms));
let failures = 0;
const ok = (name, pass, detail = '') => {
  failures += pass ? 0 : 1;
  console.log(`${pass ? 'pass' : 'FAIL'}  ${name}${pass || !detail ? '' : '  — ' + detail}`);
};
const eq = (name, got, want) => ok(name, JSON.stringify(got) === JSON.stringify(want),
  `got ${JSON.stringify(got)}, want ${JSON.stringify(want)}`);

// ---- CDP ------------------------------------------------------------------------------------

async function pageTarget() {
  for (let i = 0; i < 50; i++) {
    try {
      const list = await (await fetch(`http://127.0.0.1:${CDP}/json/list`)).json();
      const page = list.find(t => t.type === 'page');
      if (page) return page.webSocketDebuggerUrl;
    } catch { /* Chromium is still coming up */ }
    await sleep(200);
  }
  throw new Error('no CDP page target — is Chromium running with --remote-debugging-port?');
}

const ws = new WebSocket(await pageTarget());
await new Promise(r => ws.addEventListener('open', r));
let id = 0;
const waiting = new Map();
ws.addEventListener('message', e => {
  const m = JSON.parse(e.data);
  if (m.id && waiting.has(m.id)) { waiting.get(m.id)(m); waiting.delete(m.id); }
});
const send = (method, params = {}) => new Promise((res, rej) => {
  const n = ++id;
  waiting.set(n, m => m.error ? rej(new Error(`${method}: ${m.error.message}`)) : res(m.result));
  ws.send(JSON.stringify({ id: n, method, params }));
});
const ev = async expression => {
  const r = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true });
  if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description || 'evaluate failed');
  return r.result.value;
};

await send('Page.enable');
await send('Runtime.enable');

const viewport = (w, scheme = 'light') => Promise.all([
  send('Emulation.setDeviceMetricsOverride', { width: w, height: 900, deviceScaleFactor: 1, mobile: true }),
  send('Emulation.setEmulatedMedia', { features: [{ name: 'prefers-color-scheme', value: scheme }] })
]);
=== unit.mjs head ===
// The model arithmetic, exercised in node. Everything checked here is pure: it takes files or
// date strings and returns values, with no DOM, no IndexedDB and no network - which is why it
// does not belong in the browser suite, where a date bug would surface as a misplaced cell.
//
//   node test/unit.mjs
//
// Nothing is installed and nothing is written. The output format matches check.mjs, so
// test/run.sh can print both runs as one list.
import {
  isoWeek, addDays, addMonths, diffDays, dayKeyOf, dowOf, weekStartOf, monthGrid,
  isAllDay, stageOf, importantOf, buildModel, occurrences, byStart, byImportance,
  sprintOf, sprintRange, pathFor, idTail, entryFile, groupName, setZone, toInstant, wallParts,
  timeLabel, DEFAULT_ANCHOR
} from '../calendar/data.js';

let failed = 0;
const ok = (name, pass, detail = '') => {
  if (!pass) failed++;
  console.log(`${pass ? 'pass' : 'FAIL'}  ${name}${pass || !detail ? '' : ` -- ${detail}`}`);
};
const brief = v => { const s = JSON.stringify(v); return s.length > 300 ? s.slice(0, 300) + '…' : s; };
const eq = (name, got, want) => ok(name, JSON.stringify(got) === JSON.stringify(want),
  `got ${brief(got)}, wanted ${brief(want)}`);

// ---- calendar-date arithmetic -----------------------------------------------------------------
// All of it is UTC string arithmetic, so neither a zone nor a DST change can shift a bare date
// by a day. These are the cases where a local Date would have been wrong.

eq('addDays crosses a month', addDays('2026-01-31', 1), '2026-02-01');
eq('addDays crosses a leap day', addDays('2024-02-28', 1), '2024-02-29');
eq('addDays goes backwards over a year', addDays('2026-01-01', -1), '2025-12-31');
eq('addDays crosses a spring DST change', addDays('2026-03-28', 1), '2026-03-29');
eq('diffDays counts inclusive days exclusively', diffDays('2026-04-18', '2026-04-25'), 7);
eq('addMonths clamps a short month', addMonths('2026-01-31', 1), '2026-02-28');
eq('addMonths clamps into a leap February', addMonths('2024-01-31', 1), '2024-02-29');
eq('addMonths steps a year', addMonths('2026-04-18', 12), '2027-04-18');
eq('addMonths steps back over January', addMonths('2026-01-15', -1), '2025-12-15');
eq('dayKeyOf normalises an overflowing day', dayKeyOf(2026, 0, 32), '2026-02-01');
eq('dowOf reads Sunday as 0', dowOf('2026-04-19'), 0);
eq('dowOf reads Saturday as 6', dowOf('2026-04-18'), 6);
  1828 test/check.mjs
   255 test/unit.mjs
  2083 total

