  1	/* Calendar. Phone first: the desktop grid is the enhancement, not the other way round. Every
  2	   view shows seven columns beginning with the configured first day of the week, and a month
  3	   cell carries titled lines rather than dots - a Saturday task has to be readable. */
  4	
  5	/* An id or class rule for display beats the UA stylesheet's [hidden], so #cal and the modal
  6	   would both render while still carrying the attribute. */
  7	[hidden] { display: none !important; }
  8	
  9	:root { --cell: 3.3rem; --today: #1f66d0; --hour: 2.4rem; --gutter: 2rem; --tcol: 3rem; }
 10	@media (prefers-color-scheme: dark) { :root:not([data-theme="light"]) { --today: #6ea8ff; } }
 11	:root[data-theme="dark"] { --today: #6ea8ff; }
 12	
 13	body { max-width: none; padding: 0; padding-bottom: env(safe-area-inset-bottom); }
 14	#cal { display: flex; flex-direction: column; min-height: 100vh; min-height: 100dvh; }
 15	
 16	/* ---- top pane ---- */
 17	/* Three groups: the two view controls left, the period centred, the two ways out right. The
 18	   centre is centred on the pane rather than on what is left over, which is what the two equal
 19	   side tracks buy. Everything in it is drawn at twice the size it was - this is the row reached
 20	   for on every visit, and it was the smallest thing on the screen. */
 21	.topbar {
 22	  position: sticky; top: 0; z-index: 5;
 23	  display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: .3rem;
 24	  padding: max(.5rem, env(safe-area-inset-top)) .5rem .5rem;
 25	  background: var(--bg); border-bottom: 1px solid var(--line);
 26	}
 27	.tb-side { display: flex; align-items: center; gap: .3rem; min-width: 0; }
 28	.tb-side.end { justify-content: flex-end; }
 29	.tb-mid { display: flex; align-items: center; gap: .1rem; min-width: 0; }
 30	/* The period label is a button with nothing drawn on it, so hover and press are what say it is
 31	   one - the same affordance the year view's month caption uses. */
 32	.period:hover { background: var(--soft); }
 33	.period:active { background: var(--line); }
 34	.nav {
 35	  display: inline-flex; align-items: center; justify-content: center;
 36	  width: auto; min-width: 2.6rem; min-height: 2.6rem; margin: 0; padding: .3rem .45rem;
 37	  font-size: 2rem; line-height: 1; font-weight: 500; text-decoration: none;
 38	  color: var(--fg); background: var(--soft); border: 0; border-radius: .5rem;
 39	}
 40	.nav.ic svg { width: 1.8rem; height: 1.8rem; display: block; }
 41	
 42	/* A week or sprint label is long - "Sprint 7 - 02.11.2026 - 15.11.2026" is wider than a narrow
 43	   phone on its own - so the label shrinks and ellipsises rather than pushing the page sideways.
 44	   The dropdown still shows the period in full. */
 45	.period {
 46	  display: inline-flex; align-items: center; justify-content: center; min-width: 0;
 47	  width: auto; margin: 0; padding: .4rem .4rem; font-size: 1.5rem; font-weight: 600;
 48	  color: var(--fg); background: none; border: 0; border-radius: .5rem;
 49	  white-space: nowrap; cursor: pointer;
 50	}
 51	#period-label { overflow: hidden; text-overflow: ellipsis; }
 52	
 53	.view { flex: 1; min-height: 0; }
 54	/* The line reports and is pressed. Nothing is drawn on it, so hover and press are what say it
 55	   is a button - the same affordance the period label uses. `.bad` needs the second class to beat
 56	   this rule's own colour, which the plain `.bad` in the Mine stylesheet is now behind. */
 57	.sync {
 58	  width: 100%; padding: .4rem .7rem; margin: 0; font: inherit; font-size: .75rem;
 59	  text-align: left; color: inherit; background: none; border: 0; border-radius: .4rem;
 60	  cursor: pointer;
 61	}
 62	.sync:hover { background: var(--soft); }
 63	.sync:active { background: var(--line); }
 64	.sync.bad { color: var(--bad); }
 65	
 66	/* ---- month ---- */
 67	.weekhead {
 68	  display: grid; grid-template-columns: repeat(7, 1fr);
 69	  padding: .35rem .25rem 0; font-size: .7rem; font-weight: 600;
 70	  color: var(--muted); text-align: center; text-transform: uppercase; letter-spacing: .04em;
 71	}
 72	.weekhead.gut, .grid.gut { grid-template-columns: var(--gutter) repeat(7, 1fr); }
 73	.weekhead span.we { color: var(--today); }
 74	
 75	.grid { display: grid; grid-template-columns: repeat(7, 1fr); gap: 1px; padding: .25rem; }
 76	/* The month fills the whole height of the window: the week rows divide what is left over
 77	   between them equally, so the grid is as tall as the screen allows rather than as tall as its
 78	   cells happen to need. The extra height goes to the cell, not to more lines - the cap is about
 79	   what a glance can read and stays four on a desktop, two on a phone. */
 80	.view.vM { display: flex; flex-direction: column; }
 81	.vM .grid { flex: 1; min-height: 0; grid-auto-rows: 1fr; }
 82	/* The week number, separated from the days by a thin vertical rule. Always ISO. */
 83	.wk {
 84	  display: flex; align-items: center; justify-content: center;
 85	  font-size: .6rem; font-variant-numeric: tabular-nums; color: var(--muted);
 86	  border-right: 1px solid var(--line);
 87	}
 88	.day {
 89	  display: flex; flex-direction: column; align-items: stretch; gap: .1rem;
 90	  min-width: 0; min-height: var(--cell); padding: .15rem .12rem;
 91	  text-align: left; color: var(--fg); background: var(--bg); border-radius: .3rem; cursor: pointer;
 92	}
 93	.day.we { background: var(--soft); }
 94	.day.out { opacity: .4; }
 95	.num {
 96	  align-self: center; min-width: 1.5rem; padding: .1rem 0;
 97	  font-size: .76rem; font-variant-numeric: tabular-nums; text-align: center;
 98	  color: var(--muted); border-radius: 999px;
 99	}
100	.day.today .num { color: #fff; background: var(--today); font-weight: 700; }
101	
102	.rows { display: flex; flex-direction: column; gap: 1px; overflow: hidden; }
103	.eline {
104	  display: flex; align-items: center; gap: .2rem;
105	  padding: .06rem .22rem; font-size: .66rem; line-height: 1.3;
106	  border-radius: .22rem; cursor: pointer;
107	}
108	.eline .when { flex: none; font-variant-numeric: tabular-nums; opacity: .8; }
109	.eline .what { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
110	/* In a month cell the title is clipped rather than ellipsised: three dots cost three characters
111	   in the one place in the app where characters are scarcest, and a clipped word already says
112	   there is more. */
113	.grid .eline .what { text-overflow: clip; }
114	.eline.done .what { text-decoration: line-through; opacity: .75; }
115	.more { font-size: .6rem; color: var(--muted); padding-left: .2rem; }
116	
117	/* The rectangular icon that moves a task straight to done. */
118	.tick {
119	  flex: none; width: .95rem; height: .72rem; margin: 0; padding: 0;
120	  background: none; border: 1.5px solid currentColor; border-radius: 2px;
121	  opacity: .75; cursor: pointer;
122	}
123	.tick.on { background: currentColor; opacity: 1; }
124	
125	/* ---- year ---- */
126	/* At most six months to a row, so a year reads as two even rows rather than as ten and then
127	   two - and the five gaps have to come out of the share, or six tracks plus five gaps are wider
128	   than the container and auto-fill settles for five. */
129	.year {
130	  display: grid; gap: .7rem; padding: .5rem;
131	  grid-template-columns: repeat(auto-fill, minmax(max(10.5rem, (100% - 5 * .7rem) / 6), 1fr));
132	}
133	/* A caption that is a button: clicking it zooms into that month. The whole label is the
134	   target, because a day in a year grid is not finger-sized. */
135	.ycap {
136	  display: block; width: 100%; margin: 0 0 .25rem; padding: .15rem .2rem;
137	  font: inherit; font-size: .8rem; font-weight: 600; text-align: left;
138	  color: var(--fg); background: none; border: 0; border-radius: .3rem; cursor: pointer;
139	}
140	.ycap:hover { background: var(--soft); }
141	.ycap:active { background: var(--line); }
142	.ygrid { display: grid; grid-template-columns: repeat(7, 1fr); gap: 1px; }
143	.ywh { font-size: .55rem; color: var(--muted); text-align: center; text-transform: uppercase; }
144	.ywh.we { color: var(--today); }
145	.yday {
146	  width: auto; margin: 0; padding: .2rem 0;
147	  font-size: .62rem; font-variant-numeric: tabular-nums; font-weight: 500;
148	  color: var(--fg); background: none; border: 0; border-radius: .2rem; cursor: pointer;
149	}
150	.yday.out { visibility: hidden; }
151	.yday.today { outline: 2px solid var(--today); outline-offset: -2px; font-weight: 700; }
152	
153	/* ---- week and day: columns are the days, rows are the 24 hours ---- */
154	.tg { display: flex; flex-direction: column; height: 100%; min-height: 0; }
155	.tg-head, .tg-allday, .tg-body {
156	  display: grid; grid-template-columns: var(--tcol) repeat(var(--cols), 1fr);
157	}
158	.tg-head { border-bottom: 1px solid var(--line); }
159	.tcorner { font-size: .6rem; color: var(--muted); align-self: center; text-align: center; }
160	.tgd { padding: .3rem 0; text-align: center; cursor: pointer; }
161	.tgd.we { background: var(--soft); }
162	.tgd .dw { display: block; font-size: .62rem; color: var(--muted); text-transform: uppercase; }
163	.tgd .dn { display: block; font-size: .95rem; font-weight: 600; }
164	.tgd.today .dn { color: var(--today); }
165	
166	.tg-allday { border-bottom: 1px solid var(--line); }
167	.adcell {
168	  display: flex; flex-direction: column; gap: 1px; min-height: 1.5rem; padding: 2px;
169	  border-left: 1px solid var(--line); cursor: pointer;
170	}
171	.adcell.we { background: var(--soft); }
172	
173	.tg-body { flex: 1; min-height: 0; overflow-y: auto; }
174	.hours { display: grid; grid-template-rows: repeat(24, var(--hour)); }
175	.hr {
176	  font-size: .58rem; color: var(--muted); text-align: right; padding-right: .25rem;
177	  font-variant-numeric: tabular-nums;
178	}
179	.tcol {
180	  position: relative; height: calc(24 * var(--hour));
181	  border-left: 1px solid var(--line); cursor: pointer;
182	  background: repeating-linear-gradient(to bottom, var(--line) 0 1px, transparent 1px var(--hour));
183	}
184	.tcol.we { background-color: var(--soft); }
185	.tev {
186	  position: absolute; left: 2px; right: 2px; min-height: 1rem; overflow: hidden;
187	  padding: .1rem .3rem; font-size: .68rem; line-height: 1.25;
188	  border-radius: .3rem; cursor: pointer;
189	}
190	.tev .when { display: block; font-variant-numeric: tabular-nums; opacity: .85; }
191	.tev .what { display: block; font-weight: 600; }
192	.tev .meta { display: block; font-size: .62rem; opacity: .85; }
193	.tev.done .what { text-decoration: line-through; }
194	.tev .tick { position: absolute; top: .22rem; right: .22rem; }
195	
196	/* ---- kanban ---- */
197	/* The board is capped and centred where the calendar window is as wide as the browser: a card
198	   is read at the width a sentence is read at, and a third of a wide monitor is mostly empty
199	   card. The cap is here rather than on #cal, which would narrow the pane with it. */
200	.kb {
201	  display: grid; grid-template-columns: repeat(3, 1fr); gap: .5rem; padding: .5rem;
202	  max-width: 78rem; margin-inline: auto;
203	}
204	/* Stacked: the three stages one under the other, each full width, read by scrolling down. */
205	.kb.vert { grid-template-columns: 1fr; }
206	.view.vK.one { overflow: hidden; }
207	/* Exactly one column is visible. The strip is shifted by whole multiples of its own width, so
208	   it must carry neither gap nor padding - either one leaves a sliver of the next column at the
209	   edge of the screen. The spacing lives inside each column instead. */
210	.one .kb {
211	  grid-template-columns: repeat(3, 100%); gap: 0; padding: 0; max-width: none;
212	  transform: translateX(calc(var(--col) * -100%)); transition: transform .18s ease-out;
213	}
214	.one .kcol { margin: .5rem; }
215	.kcol {
216	  display: flex; flex-direction: column; gap: .4rem;
217	  padding: .4rem; background: var(--soft); border-radius: .6rem;
218	}
219	/* The state's name is centred on the column and carries that stage's colour; the `+` sits at the
220	   right, where it is the board's only way to make a task. Two equal side tracks, so the name is
221	   centred on the column rather than on what the `+` leaves over. */
222	.khead { display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: .3rem; }
223	.kmid { display: flex; align-items: center; justify-content: center; gap: .2rem; min-width: 0; }
224	.kname {
225	  text-transform: capitalize; font-size: 1.6rem; font-weight: 700; line-height: 1.15;
226	  overflow: hidden; text-overflow: ellipsis;
227	}
228	/* The header's pagers are bigger and sit on a background of their own, so they cannot be read
229	   as a card's move buttons, which do something else entirely. The background itself is set in
230	   the phone block below - `.ib` resets it further down this sheet at the same specificity, so a
231	   rule here loses on order, which is why the pager had none at all. A disabled arrow keeps none
232	   either way, and that is what tells it from the one that still works. */
