      if (p) return p.webSocketDebuggerUrl;
    } catch {}
    await sleep(200);
  }
  throw new Error('no CDP target');
}
const ws = new WebSocket(await target());
await new Promise(r => ws.addEventListener('open', r));
let id = 0; const waiting = new Map();
ws.addEventListener('message', e => {
  const m = JSON.parse(e.data);
  if (m.id && waiting.has(m.id)) { waiting.get(m.id)(m); waiting.delete(m.id); }
});
const send = (method, params = {}) => new Promise((res, rej) => {
  const n = ++id;
  waiting.set(n, m => m.error ? rej(new Error(m.error.message)) : res(m.result));
  ws.send(JSON.stringify({ id: n, method, params }));
});
const ev = async expression => {
  const r = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true });
  if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description || 'failed');
  return r.result.value;
};
await send('Page.enable'); await send('Runtime.enable');

// The properties a split could plausibly change, read off every element on the screen.
const PROBE = `(() => {
  const want = ['display','width','height','padding','margin','font','fontSize','fontWeight',
    'fontFamily','color','backgroundColor','border','borderRadius','maxWidth','textAlign',
    'position','gap','flex','overflowY','boxShadow','whiteSpace','opacity','lineHeight'];
  const out = {};
  const seen = new Map();
  for (const n of document.querySelectorAll('body, body *')) {
    if (!n.offsetParent && n !== document.body && getComputedStyle(n).position !== 'fixed') continue;
    const key = n.tagName.toLowerCase() + (n.id ? '#' + n.id : '') +
      (n.className && typeof n.className === 'string' ? '.' + n.className.trim().replace(/\\s+/g, '.') : '');
    const i = (seen.get(key) ?? -1) + 1; seen.set(key, i);
    const cs = getComputedStyle(n);
    out[key + '[' + i + ']'] = Object.fromEntries(want.map(p => [p, cs[p]]));
  }
  out['__doc'] = { over: document.documentElement.scrollWidth - document.documentElement.clientWidth };
  return out;
})()`;

// Seed the config so the root app shows the tile screen rather than the setup form, then the
// settings screen, which is where the prefs rows and the verify list live.
const SEED = origin => `(async () => {
  const db = await new Promise((res, rej) => {
    const r = indexedDB.open('mine', 1);
    r.onupgradeneeded = () => {
      const d = r.result;
      if (!d.objectStoreNames.contains('kv')) d.createObjectStore('kv');
      if (!d.objectStoreNames.contains('files')) d.createObjectStore('files', { keyPath: 'path' });
      if (!d.objectStoreNames.contains('queue')) d.createObjectStore('queue', { autoIncrement: true });
    };
    r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error);
  });
  await new Promise((res, rej) => {
    const t = db.transaction('kv', 'readwrite');
    t.objectStore('kv').put({ owner: 'demo', repo: 'mine-data', branch: 'main',
      token: 'x', expiresAt: '2026-11-30' }, 'config');
    t.oncomplete = res; t.onerror = () => rej(t.error);
  });
  return 1;
})()`;

const SCREENS = [
  ['setup', '/', null],
  ['home', '/', 'seed'],
  ['mine-settings', '/', 'settings'],
  ['calendar-month', '/calendar/', 'seed'],
  ['calendar-settings', '/calendar/', 'cal-settings']
];

async function capture(port, width, scheme) {
  const origin = `http://127.0.0.1:${port}`;
  const shots = {};
  for (const [name, path, step] of SCREENS) {
    await send('Emulation.setDeviceMetricsOverride',
      { width, height: 900, deviceScaleFactor: 1, mobile: true });
    await send('Emulation.setEmulatedMedia', { features: [{ name: 'prefers-color-scheme', value: scheme }] });
    await send('Page.navigate', { url: origin + path });
    await sleep(700);
    if (step) { await ev(SEED(origin)); await send('Page.navigate', { url: origin + path }); await sleep(1400); }
    else { await ev(`indexedDB.deleteDatabase('mine')`); await send('Page.navigate', { url: origin + path }); await sleep(900); }
    if (step === 'settings') { await ev(`document.querySelector('#to-settings').click()`); await sleep(500); }
    if (step === 'cal-settings') {
      await ev(`document.querySelector('#menu-btn').click()`); await sleep(300);
      await ev(`[...document.querySelectorAll('#menu-body .mrow')].find(b => /settings/.test(b.textContent)).click()`);
      await sleep(500);
    }
    shots[name] = await ev(PROBE);
  }
  return shots;
}

const WIDTHS = [[360, 'light'], [900, 'dark']];
let diffs = 0;
for (const [w, scheme] of WIDTHS) {
  const before = await capture(8801, w, scheme);
  const after = await capture(8802, w, scheme);
  for (const screen of Object.keys(before)) {
    const b = before[screen], a = after[screen];
    const keys = [...new Set([...Object.keys(b), ...Object.keys(a)])];
    for (const k of keys) {
      if (!b[k]) { console.log(`+ ${w}/${scheme} ${screen} ${k} (new element)`); diffs++; continue; }
      if (!a[k]) { console.log(`- ${w}/${scheme} ${screen} ${k} (element gone)`); diffs++; continue; }
      for (const p of Object.keys(b[k])) {
        if (b[k][p] !== a[k][p]) {
          console.log(`~ ${w}/${scheme} ${screen} ${k} ${p}: ${b[k][p]} -> ${a[k][p]}`);
          diffs++;
        }
      }
    }
  }
}
console.log(diffs ? `\n${diffs} difference(s)` : '\nno computed-style differences');
ws.close();
process.exit(0);
