for f in app.js shared/ui.js shared/sync.js shared/github.js calendar/app.js calendar/ui.js calendar/settings.js; do
  echo "=== $f ==="
  node -e '
    const fs=require("fs"); const src=fs.readFileSync(process.argv[1],"utf8");
    const body=src.replace(/^import[\s\S]*?from\s*"[^"]*";|^import[\s\S]*?from\s*.[^.]*.;/gm,"");
    const names=new Set();
    for (const m of src.matchAll(/^import\s*\{([^}]*)\}\s*from/gm))
      m[1].split(",").forEach(n=>{ n=n.trim().split(/\s+as\s+/).pop().trim(); if(n) names.add(n); });
    const reexport=[...src.matchAll(/^export\s*\{([^}]*)\}\s*from/gm)].map(m=>m[1]).join(",");
    const rest=src.replace(/^import\s*\{[^}]*\}\s*from[^\n]*\n/gm,"").replace(/^export\s*\{[^}]*\}\s*from[^\n]*\n/gm,"");
    for (const n of names) {
      const used=new RegExp("\\b"+n.replace(/[$]/g,"\\$")+"\\b").test(rest) || new RegExp("\\b"+n+"\\b").test(reexport);
      if (!used) console.log("  UNUSED import:", n);
    }
  ' "$f"
done; echo "(no UNUSED lines = clean)"

